using System; using System.IO; using System.Threading; using System.Threading.Tasks; using Xunit; using AlKhayal.Application.Authentication; using AlKhayal.Data.Authentication; using AlKhayal.Data.Database;
namespace AlKhayal.IntegrationTests { public sealed class AuthServicePersistenceTests { [Fact] public async Task Auth_session_survives_new_service_instance(){var path=Path.Combine(Path.GetTempPath(),Guid.NewGuid()+".db");try{var cs=Db.ConnectionStringFor(path);Migrator.Run(cs);var users=new SqliteUserStore(cs);await users.CreateAsync("integration","مستخدم التكامل",new PasswordHasher().Hash("secret"),"administrator",CancellationToken.None);var auth=new AuthService(users,new SqliteSessionStore(cs),new PasswordHasher(),new SecureTokenGenerator(),new SystemClock());var login=await auth.LoginAsync(new LoginCommand{Username="integration",Password="secret"},CancellationToken.None);var next=new AuthService(users,new SqliteSessionStore(cs),new PasswordHasher(),new SecureTokenGenerator(),new SystemClock());var restored=await next.GetCurrentUserAsync(login.SessionToken,CancellationToken.None);Assert.NotNull(restored);Assert.Equal("مستخدم التكامل",restored.DisplayName);Assert.True(await next.ValidateCsrfAsync(login.SessionToken,login.CsrfToken,CancellationToken.None));await next.LogoutAsync(login.SessionToken,CancellationToken.None);Assert.Null(await next.GetCurrentUserAsync(login.SessionToken,CancellationToken.None));}finally{System.Data.SQLite.SQLiteConnection.ClearAllPools();if(File.Exists(path))File.Delete(path);}} } }
